css:
.swatches {
  display: grid;
  gap: 8px;
  padding: 16px;
  font-family: system-ui, sans-serif;
}

.swatch {
  margin: 0;
  padding: 12px 16px;
  border: 1px solid #e4e4e7;
  border-radius: 6px;
}

.good-dark {
  color: #fafafa;
  background-color: #18181b;
}

.good-light {
  color: #27272a;
  background-color: #fed7aa;
}

.poor-grey {
  color: #d4d4d8;
  background-color: #ffffff;
}

.poor-orange {
  color: #ffffff;
  background-color: rgb(251 146 60);
}
